    bettingDesc: 'DeHub yekem platformê diafirîne ku heval dikarin bi aborî li afirînerên ku bawer dikin dê serkeftî bibin veberhênanê bikin.',
    howFracWorks: 'Perçekirin Çawa Dixebite',
    fracStep1Title: '1. Postê Mint Bike',
    fracStep1Desc: 'Mint kirinê hilbijêre, û post dibe NFT-ya ERC-1155 ku bi rastî di 1,000 perçeyên bazirganiyê de hatiye dabeşkirin. Heke tu wê derbas bikî jî post tê weşandin — tu dikarî paşê wê mint bikî.',
    fracStep2Title: '2. Biryara Afirîner',
    fracStep2Desc: 'Afirîner hildibijêrin ku ji 1,000 perçeyên xwe çendan bifiroşin, bigirin, an ji civaka xwe re belav bikin.',
    fracStep3Title: '3. Veberhênana Hevalan',
    fracStep3Desc: 'Piştgir perçeyan dikirin, dibin xwediyên berjewendiyê ku ji hemû çavkaniyên dahatê dahatên rêjeyî distînin.',
    benefitsTitle: 'Feydeyên Ji Bo Hemû Aliyan',
    forCreators: 'Ji Bo Afirîneran',
    forCreatorsDesc: 'Dahatkirina yekser, fonkirina civakê, teşwîqên lihevhatî, û dahata pasîf a jiyanê ji naveroka serkeftî.',
    forFans: 'Ji Bo Hevalan',
    forFansDesc: 'Bilindkirina aborî ji piştgirîkirina stêrên bilind, malên bazirganiyê, û beşdariya rasterast di serkeftina afirîner de.',
    forEveryone: 'Ji Bo Her Kesî',
    forEveryoneDesc: 'Sîstema berxwedêr a sansûrê, bêdestûr ku ji bo hemû beşdaran nirx diafirîne.',
