    howItWorksDesc1: 'Hebûnên te yên giştî çiqas zêde bin, tu nîşaneke bi asta bilindtir vedikî, ji reklaman bêtir qezenc dikî, û şîrket jî ji bo ku reklamê ji te re bikin bêtir didin.',
    howItWorksDesc2: 'Bi vî awayî ne tenê aliyek, lê hemû ekosîstem sûd werdigire. Afirînerên naverokê, xerîdar, xwedî û şîrketên ku li ser platformê reklamê dikin, hemû bêtir xelatan distînin.',
    howItWorksDesc3: 'Daneyên darayî yên herî bi qezenc in, û yên me bi awayekî bêhempa di yek pergalê de hatine yekkirin ku reklamder dikarin ji bo armanckirina temaşevanan bikar bînin. Ev ne tiştek e ku tu derveyî zincîrê (off-chain) jî bikaribî bikî, ji ber ku ekstreyên bankê taybet in lê blockchain giştî ye.',
    howItWorksDesc4: 'Şiyana armanckirina "nehengan" û xerckerên mezin, û di heman demê de amadekirina peyman an daxistinên taybet ji bo masiyên piçûk ên deryayê, dê awayê reklamkirinê li seranserê cîhanê ji nû ve şekil bide. Çima kesek vê nexwaze?',
    impact: 'Bandor:',
    impactDesc: 'Ev windabûn dikare were wateya windakirina £100k-£150k li ser budçeyeke £500k, ku bandorê li ROI-ya rastîn dike',
    incentives: 'Teşwîq:',
    incentivesDesc: 'Platformên teknolojiya reklamê di dîrokê de pîvana mezin xelat kirine, ne bi pêwîstî mirovên rastîn, û vê yekê derfet ji bo sextekariyê afirandine.',
    keyFigures: 'Hejmar û meylên sereke',
    lostRoi: 'ROI-ya windabûyî:',
    lostRoiDesc: 'Rê li ber marqeyan digire ku bigihîjin armancên xwe, heta bi kampanyayên mezin jî.',
    povrDesc1: 'Çareseriya me ya teknolojiya reklamê ne mîna tiştekî din e ku li bazarên kevneşopî an blockchain hatiye dîtin, û di nav sepana me de armanceke bêhempa pêk tîne.',
    povrDesc2: '"Proof of View" (îsbata temaşekirinê) yek-alî ye û ji bilî naskirinê, ji bo bikarhêner an xwediyan feydeyeke kêm tîne.',
    povrDesc3: 'Heke te bikaribûya îsbat bikira ku temaşevan rastîn in bêyî ku cihê blokê an gas bi heder biçe? Heke te bikaribûya daneyên darayî yên her cuzdanekê bikar bîna, ne tenê ji bo kêmkirina lêçûnan, lê her wiha ji bo bilindkirina ROI-ya kampanyayên xwe heta asta herî jor? Ne tenê bêtir pere teserûf bike, bêtir jî qezenc bike!',
    povrDesc4: 'Nermalava me, ku patentên wê di pêvajoyê de ne, vê yekê bi pergaleke rêzkirinê ya 13-astî ya bêhempa pêk tîne ku bi nîşanên me yên piştrastkirinê re tê hevgirtin; ev nîşan di danasîna taybetmendiyê ya berê de hatibûn ronîkirin.',
    povrDesc5: 'Em navê wê dikin "proof-of-view-and-rank" (îsbata temaşekirin û astê) an jî "POVR".',
    povrTitle: 'POVR: Îsbata temaşekirin û astê',
    preventFraud: 'Ev çawa rê li ber sextekariyê digire?',
    preventFraudDesc1: 'Bikaranîna botan kêmtir bi qezenc dibe, ji ber ku çalakî li ser zincîrê (on-chain) tê şopandin; bi vî awayî kesên xerab bi hêsanî bi hev ve têne girêdan û di dawiyê de hemû bingeha bikarhêneran tê paqijkirin. Reklamder astên bilindtir dikin armanc û li qata jêrîn, ku sextekariya mayî lê dimîne, nirxeke derxistinê ya herî kêm dihêlin. Ji bilî vê, moderasyona me ya nenavendî rê dide ku çalakiyên neqanûnî bi bandortir werin dîtin û pêşî li wan were girtin.',
    preventFraudDesc2: 'Ji bo agahiyên bêtir li ser parvekirina dahata reklamê ya me, li vê mijarê û kaxeza me ya spî ya li jêr binêre. Her wiha, me bişopîne da ku hemû nûçeyên herî dawî yên li ser taybetmendî û nûkirinên sepanê bistînî.',
    problemAmount: 'salê $84 milyar heta zêdetirî $125 milyar',
    problemDesc: 'Sextekariya reklamê her sal bi milyaran zirarê dide karsaziyan; texmînên ji bo 2023-2024 ev in:',
    problemDesc2: ', û tê pêşbînîkirin ku heta 2028an bigihîje $170 milyar. Sextekar botên pêşketî û taktîkan bikar tînin da ku lêçûna reklamê bidizin, ev yek bandorê li pîvan û ROI dike, û bi gelemperî ~%20-30 ê lêçûna dîjîtal li ser seredanên sexte bi heder diçe.',
