    heading: 'Hişyariya Qanûnî',
    paragraph1: 'Hemû agahdariyên ku ji hêla tîma DeHub, civak an şirîkên ve rasterast an nerasterast hatine peyda kirin tenê ji bo armancên agahdariya gelemperî an pêşvebirinê ne.',
